// max_array
//------------------------------------------------------------------------------
//
// Requires that the input vector is non‐empty.  Ensures that the return
// value is at least as large as every element of the vector, and that it
// actually occurs somewhere in the vector.

#[requires(a.len() > 0)]
#[ensures(forall(|i: usize| i < a.len() ==> result >= a[i]))]
#[ensures(exists(|i: usize| i < a.len() && result == a[i]))]
pub fn max_array(a: &Vec<i32>) -> i32 {
    // Initialize `max` to the first element; safe because len > 0.
    let mut max = a[0];

    // We now scan indices 1..a.len(), maintaining:
    //   1) `max` is >= all elements a[0..idx)
    //   2) there is some j < idx with a[j] == max
    // and we decrease on the remaining number of elements: a.len() - idx.
    #[invariant(forall(|j: usize| j < idx ==> max >= a[j]))]
    #[invariant(exists(|j: usize| j < idx && max == a[j]))]
    #[decreases(a.len() - idx)]
    for idx in 1..a.len() {
        let value = a[idx];
        if value > max {
            max = value;
        }
    }

    max
}

